import { HEADER_TOOL_NAME } from "./constants.js";

export { HEADER_TOOL_NAME };

/**
 * Frozen instruction text. Do not edit this file.
 * The file name and the extra-field key list are the only insertions.
 */

export const SYSTEM_PROMPT =
  "You are a line-item extractor. Inspect the file and keep only rows that request a material, spare, or service. Write one compact buy line (description, quantity, unit, currency, manufacturers) then the next, until every buy line in this part is written. Do not paste long specifications. Do not write item-number-only objects. Map whatever labels this file uses. Do not invent values. Manufacturer is the company name only. Skip questions, instructions, attachments, and commercial terms.";

export const headerUserText = (originalName: string) =>
  [
    `File name: "${originalName}".`,
    `Read the header of this customer document and call ${HEADER_TOOL_NAME} once.`,
    "Use an empty string for any field the document does not show. Never guess.",
    "Fields the bidder must fill in (blank boxes, questionnaire answers) are not values.",
    "Our own company appears as the supplier or vendor on some forms; it is never the customer.",
  ].join(" ");

export const lineUserText = (input: {
  originalName: string;
  ext: string;
  hasText: boolean;
  extraFieldKeys: string[];
}) => {
  const { originalName, ext, hasText, extraFieldKeys } = input;
  return [
    ext === ".txt"
      ? `Extract every requested buy line from this customer email body ("${originalName}"). If this is only a part of the message, extract every buy line in this part.`
      : `Extract every requested buy line from this customer file named "${originalName}". If this is only a part of the file, extract every buy line in this part.`,
    ext === ".txt"
      ? "This text is the customer email. Buy lines may be written in the message. Read them in order."
      : hasText
        ? "The rows below are the file text. Read them in order."
        : "These are buyer requests, not vendor quotes. Use OCR on scans and embedded images.",
    "Layouts vary (RFX printouts, Excel bid sheets, PDF tables, Word specs, enquiry workbooks). The attachment may be HTML, Word XML, or a table dump — read the visible labels and values yourself, including HTML entities. Map whatever labels and columns this file uses. Do not invent values.",
    "A buy line is a material, spare, or service the supplier must quote. A numbered row is not a buy line when it is a question, instruction, attachment, commercial term, or bid-form field.",
    "Treat each buy line as one block: from its item number (or table row) until the next item. Collect quantity, unit, manufacturers, part numbers, and notes from that whole block. Do not stop at the title. Do not write an item object until that block's description, quantity, unit, currency, and manufacturers are filled. Then write the complete object and move on.",
    "customerItemNumber: the printed item/line/position number only. Keep every dot and leading zero. If the title starts with that number, put the number here and the rest in description. Never use the document, PR, event, or file number. Do not invent a number. A digit inside a product code is not an item number.",
    "description: the item text. Do not leave it empty when the row has item text.",
    "productName: a short readable catalog name you write from the description. Do not copy a class/material code, long PO text, manufacturer, or part number. Leave empty when there is no description.",
    "manufacturers: one object per manufacturer option on this buy line. Find them wherever this file puts them — Manufacturer / Mfr / OEM columns, P/N or MPN beside a company name, or a part number paired later in the same block with a company name. Empty bid-form manufacturer boxes are not makers. Company name only — not vendor id, city, country, or street. Do not join names into one string. Do not invent a maker or part number. Never emit a manufacturer as its own line.",
    "partNumber and manufacturer strings are fallbacks only when manufacturers is empty.",
    "quantity and unitOfMeasure are two fields. quantity: the number only. unitOfMeasure: a short standard code, not the printed spelling. Convert any notation yourself: Pieces, Piece, PCS, PCE, PC, Each, EA, Nos, No, Nr → PCS. Other examples: kilogram/kgs → KG, metre/meter/mtr → M, litre/liter → L, set/sets → SET, box/boxes → BOX. Use the same code for the same unit on every line. If the file prints quantity and unit together, split them yourself. If the block shows a quantity, always return it.",
    "currency: a 3-letter ISO code from the printed Currency / RFP Currency field, stamps, or line columns. Convert a printed name yourself (US Dollar → USD, UAE Dirham → AED, Euro → EUR). If the file has one header currency, put that ISO code on every buy line unless a line shows a different currency. Do not infer AED from a UAE buyer or ADNOC name when the file prints US Dollar. Leave empty only when the file shows no currency at all.",
    "technicalSpecification: at most two short sentences for this line. Do not paste classification lists, characteristics, or page headers.",
    ...(extraFieldKeys.length
      ? [
          `extraFields: fill ${extraFieldKeys.join(", ")} from this buy line's own block (its long text, classification, MPN and inspection sections included). Leave a field empty when this line does not show it — never copy a value from another line or guess.`,
        ]
      : []),
    "Keep every buy line that has a description, manufacturer, or part number.",
    "Never output placeholders such as UNKNOWN, N/A, None, or null.",
    "Put items in file order. Keep every object compact and emit every buy line in this part. A numbered row with a material number, quantity, and unit is its own buy line even when a long specification follows it.",
  ].join(" ");
};
